referenceSolutions.javascript:
export function solve(initial, operations) {
  let classes = initial.slice();
  return operations.map(([op, name]) => {
    const has = classes.includes(name);
    if (op === "remove" || (op === "toggle" && has)) classes = classes.filter((x) => x !== name);
    else if (!has) classes.push(name);
    return classes.slice();
  });
}

referenceSolutions.typescript:
type Value = any;
export function solve(initial: Value, operations: Value): Value {
  let classes = initial.slice();
  return operations.map(([op, name]: Value) => {
    const has = classes.includes(name);
    if (op === "remove" || (op === "toggle" && has))
      classes = classes.filter((x: Value) => x !== name);
    else if (!has) classes.push(name);
    return classes.slice();
  });
}
